/** Replays retained native bytes with the SAME canonical codec/oracles. Never
 * executes SQL or imports application, database, provider or Vitest modules. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
import {employeeChoiceNativeLogBounds as bounds,employeeChoiceNativeLogPartBytes,employeeChoiceNativeLogRecords,employeeChoiceNativePlanPhases,employeeChoiceNativeInvocations,employeeChoiceSqlFingerprint,employeeChoiceNativeBody,employeeChoicePlanWork} from './employee-native-log-codec.mjs';
const sha=value=>createHash('sha256').update(value).digest('hex');
const phases=Object.freeze(['initial:0','initial:1','deep:0','search:0','department-active:0','department-active:1','department-and-unit:0','unit-active:0','organisation-deep:0','organisation-search:0','empty-unit:0','missing-search:0','broad-search:0','deep-broad-search:0','foreign-company:0','complete-ids:0','held-access:0','held-history:0','full-server-population:0','full-server-ids:0','full-server-search-population:0','sparse-server-population:0']);
const portNames=phases.map(label=>label.slice(0,label.lastIndexOf(':'))).filter((name,index,all)=>all.indexOf(name)===index&&!['full-server-ids','sparse-server-population'].includes(name));
export const employeeLifecycleNativeSql=file=>file==='test/employee-choice-exact-ascii-plan.test.ts'?'test/fixtures/employee-choice-exact-ascii-purpose.sql':file==='test/employee-choice-native-purpose-plan.test.ts'?'test/fixtures/employee-choice-native-purpose.sql':null;
function expectedCalls(name,ascii){
 const candidates={initial:25,deep:25,search:ascii?1:50000,'department-active':25,'department-and-unit':25,'unit-active':25,'organisation-deep':25,'organisation-search':ascii?1:500,'empty-unit':0,'missing-search':ascii?0:50000,'broad-search':ascii?25:50000,'deep-broad-search':ascii?25:50000};
 const special={'foreign-company':1,'complete-ids':400,'full-server-population':2005,'full-server-search-population':ascii?2005:50005,'full-server-ids':50000,'sparse-server-population':7,'held-access':30,'held-history':30};
 assert(Object.hasOwn(candidates,name)||Object.hasOwn(special,name));const first={port:['complete-ids','full-server-ids'].includes(name)?'ids':'page',rows:Object.hasOwn(special,name)?special[name]:5+candidates[name]};
 if(name==='initial'||name==='deep')first.pagination={total:50000,offset:name==='deep'?49975:0,limit:25};
 if(name==='full-server-population')return[{...first,serverScopeIds:50000,pagination:{total:50000,offset:48000,limit:2000}}];
 if(name==='full-server-search-population')return ascii?[{...first,serverScopeIds:50000,pagination:{total:50000,offset:48000,limit:2000}}]:[{...first,serverScopeIds:50000},{port:'project',rows:2001,matchedIds:50000,serverScopeIds:50000,assignmentPageRows:2000,pagination:{total:50000,offset:48000,limit:2000}}];
 if(name==='full-server-ids')return[{...first,serverScopeIds:50000}];
 if(!ascii&&name==='search')return[first,{port:'project',rows:2,matchedIds:1,assignmentPageRows:1}];
 if(!ascii&&name==='organisation-search')return[first,{port:'project',rows:2,matchedIds:1}];
 if(name==='broad-search'||name==='deep-broad-search'){const pagination={total:50000,offset:name==='deep-broad-search'?49975:0,limit:25};return ascii?[{...first,pagination}]:[first,{port:'project',rows:26,matchedIds:50000,assignmentPageRows:25,pagination}];}
 return[first];
}
/** Pure replay. API owner and lifecycle verifier separately authenticate members. */
export function verifyEmployeeLifecycleNativePlans({plan,unit,profile,members,sourceSql,resource,job}){
 const directory=profile.clockDirectory,ascii=profile.stage==='ascii-plan',sqlFile=employeeLifecycleNativeSql(profile.file);assert(sqlFile&&Buffer.isBuffer(sourceSql));assert.equal(sha(sourceSql),plan.singletonSources[unit.id][sqlFile]);
 const read=(name,max)=>{const value=members.get(directory+'/'+name);assert(Buffer.isBuffer(value)&&value.length>0&&value.length<=max,'Missing bounded retained native bytes');return value;};
 const report=JSON.parse(read(ascii?'employee-choice-exact-ascii-plan.json':'employee-choice-native-purpose-plan.json',67108864));
 for(const key of ['complete','preparationComplete','actualPlansComplete','instrumentationRestored','authorityComplete','cleanupComplete'])assert.equal(report[key],true);assert.equal(report.registration,'full-ci-singleton');assert.equal(report.phase,'complete');assert.equal(report.lifetime?.started,true);assert.equal(report.lifetime?.finished,true);for(const key of ['stopped','pending','cancellationPending','uncertain'])assert.equal(report.lifetime[key],false);assert.equal(report.lifetime.workBudgetMs,840000);assert.equal(report.lifetime.totalBudgetMs,900000);assert.equal(report.lifetime.reserveMs,60000);assert(typeof report.lifetime.elapsedMs==='number'&&report.lifetime.elapsedMs>=0&&report.lifetime.elapsedMs<=900000);assert.equal(report.failedCase,false);assert.equal(report.sessionPoisoned,false);assert.equal(report.releaseEligible,false);assert.equal(report.productionPolicyApproved,false);assert.equal(report.migrationAllocated,false);assert.equal(report.employees,50000);assert.equal(report.actualPlanCases,44);assert.equal(report.actualNativeCallPairs,profile.callPairs);assert.deepEqual(report.planVerificationFailures,[]);
 assert.equal(report.prototypeCleanupWitness?.restorationAccepted,true,'Native function restoration has no source-executed terminal acceptance');assert.equal(report.loggingCleanupWitness?.restorationAccepted,true,'Native logging restoration has no source-executed terminal acceptance');
 assert.deepEqual(report.variants,['current','native']);assert.deepEqual(report.performanceVariants,['current','native']);assert.equal(report.targetMs,1000);assert.equal(report.wholePortsPerVariant,18);
 const replay=replayEmployeeLifecycleNativeLog({plan,unit,profile,members,sourceSql,resource,job,report});
 const ports=Object.keys(report.ports).filter(key=>key.startsWith('native:')).sort();assert.deepEqual(ports,portNames.map(name=>'native:'+name).sort());const measured=[];
 for(const key of ports){const port=report.ports[key],name=key.slice('native:'.length),arrayPort=phases.slice(0,15).some(label=>label.slice(0,label.lastIndexOf(':'))===name);const samples=arrayPort?port.samples:[port.ms];assert(Array.isArray(samples)&&samples.length===(arrayPort&&['initial','department-active'].includes(name)?2:1)&&samples.every(value=>typeof value==='number'&&Number.isFinite(value)&&value>=0));measured.push({port:key,samples});}
 const performancePassed=measured.every(row=>row.samples.every(value=>value<1000));assert.equal(report.wholePortTargets.native.targetMs,1000);assert.equal(report.wholePortTargets.native.measuredPorts,18);assert.equal(report.wholePortTargets.native.allUnderTarget,performancePassed);assert(performancePassed,'performance-refused: actual native whole port exceeds unchanged1000ms target');
 return Object.freeze({...replay,measuredPorts:18,performancePassed,applicationAdoption:false});
}

/** Pure native byte replay only. This grants no lifecycle, timing, source or API
 * authority; callers must independently bind those facts. Historical receipts
 * can be replayed without relabelling their registration or failed speed gates. */
export function replayEmployeeLifecycleNativeLog({plan,unit,profile,members,sourceSql,resource,job,report}){
 const directory=profile.clockDirectory,ascii=profile.stage==='ascii-plan',sqlFile=employeeLifecycleNativeSql(profile.file);assert(sqlFile&&Buffer.isBuffer(sourceSql));assert.equal(sha(sourceSql),plan.singletonSources[unit.id][sqlFile]);
 const read=(name,max)=>{const value=members.get(directory+'/'+name);assert(Buffer.isBuffer(value)&&value.length>0&&value.length<=max,'Missing bounded retained native bytes');return value;};
 const expectedLabels=['current','native'].flatMap(variant=>phases.map(label=>variant+':'+label));assert.deepEqual(report.markers.map(row=>row.label),expectedLabels);
 const markers=report.markers.map(marker=>{const [variant,name]=marker.label.split(':');assert.equal(marker.native,variant==='native');const base='aihr_ecp_'+sha(marker.label).slice(0,24);assert.equal(marker.begin,`select 1 as "${base}_begin"`);assert.equal(marker.end,`select 1 as "${base}_end"`);const expected=variant==='native'?expectedCalls(name,ascii):undefined;assert(isDeepStrictEqual(marker.expectedNativeCalls,expected));return{...marker,expectedNativeCalls:expected};});
 const rawIndex=read('native-log-index.json',bounds.indexBytes),index=JSON.parse(rawIndex);assert.equal(index.kind,'ACTUAL_LOSSLESS_NATIVE_LOG_PARTS_NOT_RELEASE');assert.equal(index.version,1);assert.equal(index.transportClosed,true);assert.equal(index.semanticQualification,false);assert.equal(index.releaseAuthorized,false);assert(index.parts.length>0&&index.parts.length<=bounds.parts);
 const binding=index.binding;assert.equal(binding.source,plan.sha);assert.equal(binding.controller,plan.controller);assert.equal(binding.run,String(job.run_id));assert.equal(binding.attempt,'1');assert.equal(binding.containerId,resource.cid);assert.equal(binding.container,`aihr-ci-${job.run_id}-1-${unit.id}`);assert(Number.isSafeInteger(binding.pid)&&binding.pid>1);assert.equal(binding.pid,report.planBackend.pid);assert.notEqual(binding.pid,report.timingBackend.pid);for(const key of ['role','login','database','jit','context_cleared'])assert.equal(report.timingBackend[key],report.planBackend[key]);assert.equal(report.planBackend.role,'ai_hr_app');assert.equal(report.planBackend.login,'ai_hr_app');assert.equal(report.planBackend.database,'ai_hr_test_w1');assert.equal(report.planBackend.jit,'on');assert.equal(report.planBackend.context_cleared,true);
 assert.deepEqual(report.planBackendSettings,{duration:'0',parameters:'0',nested:'on',analyze:'on',buffers:'on',settings:'on',format:'json',timing:'off'});
 assert(Number.isFinite(Date.parse(binding.startedAt))&&Date.parse(binding.startedAt)>=Date.parse(resource.created)&&Date.parse(binding.startedAt)<=Date.parse(job.completed_at));
 const indexSummary={file:'native-log-index.json',sha256:sha(rawIndex),rawBytes:index.rawBytes,gzipBytes:index.gzipBytes,parts:index.parts.length,transportClosed:true};assert(isDeepStrictEqual(report.retainedFinalRaw,indexSummary));for(const [key,value]of Object.entries(indexSummary))assert.equal(report.nativeLog[key],value);for(const key of ['pid','container','containerId','startedAt'])assert.equal(report.nativeLog[key],binding[key]);assert.equal(report.nativeLog.format,'lossless-indexed-gzip-parts');assert(['stdout','stderr'].includes(report.nativeLog.channel));
 let compressed=0,rawBytes=0;const partNames=new Set();for(const [ordinal,part]of index.parts.entries()){
  assert.equal(part.sequence,ordinal+1);assert(['stdout','stderr'].includes(part.channel));assert.equal(part.file,`native-log-part-${ordinal+1}.${part.channel}.log.gz`);assert(!partNames.has(part.file));partNames.add(part.file);const gzip=read(part.file,bounds.memberBytes);compressed+=gzip.length;rawBytes+=part.rawBytes;assert(compressed<=bounds.gzipAggregateBytes&&rawBytes<=bounds.rawAggregateBytes);assert.equal(gzip.length,part.gzipBytes);
 }
 assert.equal(compressed,index.gzipBytes);assert.equal(rawBytes,index.rawBytes);for(const key of members.keys())if(key.startsWith(directory+'/native-log-part-'))assert(partNames.has(key.slice(directory.length+1)),'Unindexed native part');
 function* channel(name){let count=0;const hash=createHash('sha256');for(const part of index.parts.filter(part=>part.channel===name)){assert.equal(part.start,count);const bytes=employeeChoiceNativeLogPartBytes(read(part.file,bounds.memberBytes),part);count+=bytes.length;hash.update(bytes);yield{start:part.start,bytes};}assert.equal(count,index.channels[name].bytes);assert.equal(hash.digest('hex'),index.channels[name].sha256);}
 const selected=report.nativeLog.channel,other=selected==='stdout'?'stderr':'stdout';for(const record of employeeChoiceNativeLogRecords(channel(other)))assert.notEqual(record.pid,binding.pid,'Native PID split between unorderable channels');
 const body=employeeChoiceNativeBody(sourceSql.toString('utf8')),bodyHash=employeeChoiceSqlFingerprint(body);let phaseCount=0,pairs=0;
 for(const {label,entries}of employeeChoiceNativePlanPhases(channel(selected),binding.pid,markers,body)){
  assert.equal(label,expectedLabels[phaseCount++]);if(!label.startsWith('native:'))continue;
  const marker=markers.find(row=>row.label===label),invocations=employeeChoiceNativeInvocations(entries,body,marker.expectedNativeCalls);pairs+=invocations.length;const distinct=[];
  for(const entry of entries){const work=employeeChoicePlanWork(entry.document.Plan,report.exactWholeFixtureCardinalities);assert.deepEqual(work.rejectionReasons,[]);if(employeeChoiceSqlFingerprint(entry.query)===bodyHash){assert.equal(entry.document.Settings?.jit,'off');assert.equal(entry.document.JIT,undefined);distinct.push(work);}}
  assert(distinct.length>0);assert(distinct.reduce((n,row)=>n+row.rootSharedBlocks,0)<=distinct[0].limits.maxRootSharedBlocks);assert(distinct.reduce((n,row)=>n+row.maximumNodeWork,0)<=distinct[0].limits.maxNodeWork);
 }
 assert.equal(phaseCount,44);assert.equal(pairs,profile.callPairs);
 return Object.freeze({kind:'RAW_NATIVE_PLAN_REPLAY_NOT_LIFECYCLE_OR_SPEED',phases:phaseCount,callPairs:pairs,nativePid:binding.pid,indexSha256:sha(rawIndex),rawBytes,compressedBytes:compressed,releaseAuthorized:false});
}
